// Conditional FE Poisson validated against Stata `xtpoisson, fe` golden.
// Golden generated by tests/validate/xtpois_golden.do on the 8374-unit panel
// with treated/age_z/edu_hi covariates (female dropped: time-invariant).
#include <cmath>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "estimators/xtpois.h"
#include "io/columnar.h"
#include "validate_dir.h"

using namespace cecon;

namespace {

double parse_stata(const std::string& s) {
    if (s.empty() || s == ".") return std::nan("");
    if (s[0] == '.') return std::stod("0" + s);
    if (s.size() > 1 && s[0] == '-' && s[1] == '.') return -std::stod("0" + s.substr(1));
    return std::stod(s);
}

struct GoldRow { std::string name; double bi, sei, br, ser; };
std::vector<GoldRow> read_gold(const std::string& path) {
    std::ifstream f(path);
    std::string line;
    std::getline(f, line);
    std::vector<GoldRow> out;
    while (std::getline(f, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string nm, a, b, c, d;
        std::getline(ss, nm, ',');
        std::getline(ss, a, ',');
        std::getline(ss, b, ',');
        std::getline(ss, c, ',');
        std::getline(ss, d, ',');
        out.push_back({nm, parse_stata(a), parse_stata(b), parse_stata(c), parse_stata(d)});
    }
    return out;
}

}  // namespace

int test_xtpois_main() {
    std::printf("test_xtpois:\n");
    Dataset ds = Dataset::open(cobra_test::validate_path("csdid_input.hbin"));
    int64_t n_obs = ds.n_rows();
    const double* h_pid = ds.col("h_pid").f64();
    const double* wv    = ds.col("wv").f64();
    const double* gvar  = ds.col("gvar").f64();
    const double* y_raw = ds.col("visits_w").f64();
    const double* age_z = ds.col("age_z").f64();
    const double* edu_hi= ds.col("edu_hi").f64();

    // Build treated = 1 if gvar>0 & wv>=gvar (matching the do-file)
    // and y_int = round(visits_w).
    std::vector<double> treated(static_cast<size_t>(n_obs));
    std::vector<double> y_int(static_cast<size_t>(n_obs));
    for (int64_t i = 0; i < n_obs; ++i) {
        double g = gvar[i];
        treated[static_cast<size_t>(i)] = (g > 0 && wv[i] >= g) ? 1.0 : 0.0;
        y_int[static_cast<size_t>(i)] = std::isnan(y_raw[i]) ? std::nan("")
                                                            : std::round(y_raw[i]);
    }

    // Mask off missing y_int rows.
    std::vector<int64_t> keep;
    keep.reserve(static_cast<size_t>(n_obs));
    for (int64_t i = 0; i < n_obs; ++i)
        if (!std::isnan(y_int[static_cast<size_t>(i)])) keep.push_back(i);
    int64_t n_keep = static_cast<int64_t>(keep.size());

    int k = 3;
    std::vector<double> X(static_cast<size_t>(n_keep) * k);
    std::vector<double> y(static_cast<size_t>(n_keep));
    std::vector<double> ivar(static_cast<size_t>(n_keep));
    for (int64_t i = 0; i < n_keep; ++i) {
        int64_t r = keep[static_cast<size_t>(i)];
        y[static_cast<size_t>(i)]    = y_int[static_cast<size_t>(r)];
        ivar[static_cast<size_t>(i)] = h_pid[r];
        X[static_cast<size_t>(0) * n_keep + i] = treated[static_cast<size_t>(r)];
        X[static_cast<size_t>(1) * n_keep + i] = age_z[r];
        X[static_cast<size_t>(2) * n_keep + i] = edu_hi[r];
    }

    auto R = xtpoisson_fe(X.data(), n_keep, k, y.data(), ivar.data(), nullptr, 100, 1e-12);
    std::printf("  converged=%d iters=%d  N_obs=%lld  N_g=%lld  dropped_zero=%lld dropped_size=%lld  ll=%.6f\n",
                R.converged ? 1 : 0, R.iters,
                static_cast<long long>(R.n_obs),
                static_cast<long long>(R.n_groups),
                static_cast<long long>(R.n_dropped_zero),
                static_cast<long long>(R.n_dropped_size),
                R.loglik);

    auto golden = read_gold(cobra_test::validate_path("xtpois_golden.csv"));
    const char* names[] = {"treated", "age_z", "edu_hi"};
    double worst_b = 0, worst_seii = 0, worst_serob = 0;
    for (int c = 0; c < k; ++c) {
        // Locate the golden row by name
        double gb = 0, gsei = 0, gser = 0; bool found = false;
        for (const auto& g : golden) if (g.name == names[c]) { gb = g.bi; gsei = g.sei; gser = g.ser; found = true; }
        if (!found) { std::printf("  ! golden missing for %s\n", names[c]); continue; }
        double rb   = std::fabs(R.beta[c]   - gb)   / (std::fabs(gb)   + 1e-12);
        double rsei = std::fabs(R.se_iid[c] - gsei) / (std::fabs(gsei) + 1e-12);
        double rsr  = std::fabs(R.se_robust[c] - gser) / (std::fabs(gser) + 1e-12);
        std::printf("  %-8s: b=%+.10g (stata %+.10g  rel %.2e)  se_iid=%.10g (stata %.10g rel %.2e)  se_rob=%.10g (stata %.10g rel %.2e)\n",
                    names[c], R.beta[c], gb, rb,
                    R.se_iid[c], gsei, rsei,
                    R.se_robust[c], gser, rsr);
        if (rb   > worst_b)    worst_b    = rb;
        if (rsei > worst_seii) worst_seii = rsei;
        if (rsr  > worst_serob)worst_serob= rsr;
    }
    double stata_ll = -647210.125759292;
    double rll = std::fabs(R.loglik - stata_ll) / std::fabs(stata_ll);
    std::printf("  ll: cecon=%.6f stata=%.6f rel=%.2e\n", R.loglik, stata_ll, rll);
    std::printf("  worst: b_rel=%.2e se_iid_rel=%.2e se_rob_rel=%.2e\n",
                worst_b, worst_seii, worst_serob);

    // Stata's xtpoisson uses ~1e-5 nrtol; cecon hits machine precision. So
    // the residual gap on β is Stata's own NR residual (~1e-7), not cecon's.
    int fail = 0;
    if (!R.converged) fail = 1;
    if (worst_b > 1e-6) fail = 1;
    if (worst_seii > 1e-8) fail = 1;
    if (worst_serob > 1e-8) fail = 1;
    if (rll > 1e-10) fail = 1;
    std::printf("%s\n", fail ? "FAILED" : "PASSED");
    return fail;
}
